insert into levels (id, title, sort) values ('foundations', 'Foundations', 1) on conflict (id) do nothing;
insert into units (id, level_id, title, subtitle, color, foundation, sort) values ('pillars', 'foundations', 'The Five Pillars', 'What Islam is built on', '#2F7D5B', true, 1) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle;
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('pillars-1', 'pillars', 'Built on five', 'The Prophet ﷺ said that Islam is built on five: the testimony of faith (shahada), prayer (salah), charity (zakat), fasting in Ramadan (sawm) and pilgrimage to the House (hajj).', 1, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('pillars-1', 'choice', '{"type":"choice","prompt":"How many pillars is Islam built on?","options":["Three","Five","Six","Seven"],"answer":1,"explain":"Islam is built on five pillars.","source":{"kind":"hadith","reference":"Sahih al-Bukhari 8, Sahih Muslim 16"}}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('pillars-1', 'match', '{"type":"match","prompt":"Match each pillar to its meaning","pairs":[["Shahada","Testimony of faith"],["Salah","Prayer"],["Zakat","Obligatory charity"],["Sawm","Fasting"],["Hajj","Pilgrimage"]],"explain":"These five together are the pillars of Islam."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('pillars-1', 'choice', '{"type":"choice","prompt":"Which of these is NOT one of the five pillars?","options":["Fasting in Ramadan","Zakat","Reading the whole Quran each month","Hajj"],"answer":2,"explain":"Reading the Quran is highly rewarded, but the five pillars are shahada, salah, zakat, sawm and hajj."}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('pillars-1', 'order', '{"type":"order","prompt":"Put the pillars in the order the hadith mentions them","items":["Shahada","Salah","Zakat","Hajj","Sawm"],"explain":"In the narration of Sahih al-Bukhari 8 the order is shahada, salah, zakat, hajj, then fasting in Ramadan. Other narrations mention fasting before hajj.","source":{"kind":"hadith","reference":"Sahih al-Bukhari 8"}}'::jsonb, 4);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('pillars-2', 'pillars', 'The shahada', 'The shahada is: "Ash-hadu an la ilaha illa Allah, wa ash-hadu anna Muhammadan rasul Allah." I bear witness that there is no god but Allah, and I bear witness that Muhammad is the Messenger of Allah.', 2, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('pillars-2', 'choice', '{"type":"choice","prompt":"What does \"la ilaha illa Allah\" mean?","options":["Allah is the greatest","There is no god but Allah","All praise is for Allah","In the name of Allah"],"answer":1,"explain":"\"La ilaha illa Allah\" means there is no god worthy of worship except Allah."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('pillars-2', 'order', '{"type":"order","prompt":"Build the shahada","items":["Ash-hadu","an la ilaha","illa Allah,","wa ash-hadu anna","Muhammadan","rasul Allah"],"explain":"This is the full testimony of faith."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('pillars-2', 'choice', '{"type":"choice","prompt":"The second part of the shahada is a testimony about whom?","options":["Prophet Ibrahim","Prophet Musa","Prophet Muhammad ﷺ","Angel Jibril"],"answer":2,"explain":"The second part bears witness that Muhammad ﷺ is the Messenger of Allah."}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('pillars-2', 'match', '{"type":"match","prompt":"Match the Arabic to its meaning","pairs":[["Ash-hadu","I bear witness"],["La ilaha","There is no god"],["Illa Allah","Except Allah"],["Rasul","Messenger"]],"explain":"Knowing the meaning makes the words come alive."}'::jsonb, 4);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('pillars-3', 'pillars', 'Salah and zakat', 'Muslims pray five times every day. Zakat is a yearly charity: 2.5% of savings that stay above a minimum amount (the nisab) for a full lunar year, given to those who are eligible.', 3, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('pillars-3', 'choice', '{"type":"choice","prompt":"How many obligatory prayers are there each day?","options":["Three","Four","Five","Seven"],"answer":2,"explain":"There are five daily prayers: Fajr, Dhuhr, Asr, Maghrib and Isha."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('pillars-3', 'order', '{"type":"order","prompt":"Put the daily prayers in order, starting at dawn","items":["Fajr","Dhuhr","Asr","Maghrib","Isha"],"explain":"Fajr is at dawn, Dhuhr after midday, Asr in the afternoon, Maghrib at sunset and Isha at night."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('pillars-3', 'choice', '{"type":"choice","prompt":"What share of eligible savings is paid as zakat?","options":["1%","2.5%","10%","20%"],"answer":1,"explain":"Zakat on savings is 2.5% once they stay above the nisab for a lunar year."}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('pillars-3', 'choice', '{"type":"choice","prompt":"In the Quran, which pillar is very often mentioned together with prayer?","options":["Hajj","Zakat","Fasting","Shahada"],"answer":1,"explain":"Allah often says \"establish prayer and give zakat\", for example in Al-Baqarah 2:43.","source":{"kind":"quran","reference":"Quran 2:43"}}'::jsonb, 4);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('pillars-4', 'pillars', 'Fasting and hajj', 'In Ramadan, Muslims fast from dawn (Fajr) until sunset (Maghrib), leaving food, drink and marital relations. Hajj is the pilgrimage to Makkah, required once in a lifetime for those who are able.', 4, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('pillars-4', 'choice', '{"type":"choice","prompt":"A fast in Ramadan lasts from…","options":["Sunrise to noon","Dawn to sunset","Midnight to midnight","Sunset to dawn"],"answer":1,"explain":"The fast begins at dawn (Fajr) and ends at sunset (Maghrib)."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('pillars-4', 'choice', '{"type":"choice","prompt":"Why did Allah prescribe fasting, according to Al-Baqarah 2:183?","options":["To lose weight","So that you may attain taqwa","To save money","To travel"],"answer":1,"explain":"\"Fasting is prescribed for you… so that you may become mindful of Allah (taqwa).\"","source":{"kind":"quran","reference":"Quran 2:183"}}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('pillars-4', 'choice', '{"type":"choice","prompt":"How often is hajj required?","options":["Every year","Every five years","Once in a lifetime, for those able","Never required"],"answer":2,"explain":"Hajj is an obligation once in a lifetime for those who are able to make the journey.","source":{"kind":"quran","reference":"Quran 3:97"}}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('pillars-4', 'match', '{"type":"match","prompt":"Match each pillar to when it happens","pairs":[["Sawm","The month of Ramadan"],["Hajj","The month of Dhul Hijjah"],["Salah","Five times every day"],["Zakat","Once a lunar year"]],"explain":"Each pillar has its own time."}'::jsonb, 4);
insert into units (id, level_id, title, subtitle, color, foundation, sort) values ('prayer', 'foundations', 'How to Pray', 'Wudu and the steps of salah', '#2E6FA3', true, 2) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle;
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('prayer-1', 'prayer', 'Wudu', 'Wudu is the washing done before prayer. The Quran (5:6) commands washing the face, the arms up to the elbows, wiping the head, and washing the feet up to the ankles. The Sunnah adds rinsing the mouth and nose, and starting with the hands.', 1, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('prayer-1', 'order', '{"type":"order","prompt":"Put the steps of wudu in order","items":["Intention and Bismillah","Wash the hands","Rinse the mouth","Rinse the nose","Wash the face","Wash the arms to the elbows","Wipe the head and ears","Wash the feet to the ankles"],"explain":"This is the common order of wudu taught from the Sunnah.","source":{"kind":"quran","reference":"Quran 5:6"}}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('prayer-1', 'choice', '{"type":"choice","prompt":"Up to where are the arms washed in wudu?","options":["The wrists","The elbows","The shoulders","Only the fingers"],"answer":1,"explain":"The arms are washed up to and including the elbows.","source":{"kind":"quran","reference":"Quran 5:6"}}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('prayer-1', 'choice', '{"type":"choice","prompt":"Which part is wiped, not washed?","options":["The face","The feet","The head","The arms"],"answer":2,"explain":"The head is wiped with wet hands."}'::jsonb, 3);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('prayer-2', 'prayer', 'Prayers and rak‘ahs', 'Each prayer is made of units called rak‘ahs. Fajr has 2, Dhuhr 4, Asr 4, Maghrib 3 and Isha 4. These are the obligatory (fard) rak‘ahs.', 2, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('prayer-2', 'match', '{"type":"match","prompt":"Match each prayer to its fard rak‘ahs","pairs":[["Fajr","2"],["Maghrib","3"],["Dhuhr","4"]],"explain":"Asr and Isha also have 4 fard rak‘ahs."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('prayer-2', 'choice', '{"type":"choice","prompt":"How many fard rak‘ahs does Maghrib have?","options":["2","3","4","5"],"answer":1,"explain":"Maghrib is the only daily prayer with 3 rak‘ahs."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('prayer-2', 'choice', '{"type":"choice","prompt":"How many fard rak‘ahs are there in a full day?","options":["15","17","19","20"],"answer":1,"explain":"2 + 4 + 4 + 3 + 4 = 17."}'::jsonb, 3);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('prayer-3', 'prayer', 'Steps of a rak‘ah', 'A rak‘ah moves through standing, bowing (ruku‘), rising, prostrating (sujud), sitting, and prostrating again. The prayer opens with "Allahu Akbar" and ends with the tashahhud and the salam.', 3, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('prayer-3', 'order', '{"type":"order","prompt":"Put the first rak‘ah in order","items":["Takbir: \"Allahu Akbar\"","Recite Al-Fatihah","Ruku‘ (bow)","Stand up straight","First sujud","Sit briefly","Second sujud"],"explain":"This is the shape of every rak‘ah. A short surah is usually recited after Al-Fatihah in the first two rak‘ahs."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('prayer-3', 'choice', '{"type":"choice","prompt":"Which surah is recited in every rak‘ah?","options":["Al-Ikhlas","Al-Fatihah","An-Nas","Al-Kawthar"],"answer":1,"explain":"Al-Fatihah is recited in every rak‘ah of every prayer."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('prayer-3', 'choice', '{"type":"choice","prompt":"How does the prayer end?","options":["With a sujud","With the salam to the right and left","With ruku‘","By standing up"],"answer":1,"explain":"After the final tashahhud, the prayer ends with \"As-salamu alaykum wa rahmatullah\" to the right and left."}'::jsonb, 3);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('prayer-4', 'prayer', 'What to say', 'In ruku‘ say "Subhana Rabbiya al-‘Azim" (Glory be to my Lord, the Magnificent). In sujud say "Subhana Rabbiya al-A‘la" (Glory be to my Lord, the Most High).', 4, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('prayer-4', 'match', '{"type":"match","prompt":"Match each position to what is said","pairs":[["Opening","Allahu Akbar"],["Ruku‘","Subhana Rabbiya al-‘Azim"],["Sujud","Subhana Rabbiya al-A‘la"],["Ending","As-salamu alaykum wa rahmatullah"]],"explain":"These are the core words of each position.","source":{"kind":"hadith","reference":"Sahih Muslim 772"}}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('prayer-4', 'choice', '{"type":"choice","prompt":"What does \"Subhana Rabbiya al-A‘la\" mean?","options":["Allah is the greatest","Glory be to my Lord, the Most High","All praise is for Allah","Allah hears whoever praises Him"],"answer":1,"explain":"It is said in sujud, when we are lowest to the ground."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('prayer-4', 'choice', '{"type":"choice","prompt":"When rising from ruku‘, what is said?","options":["Sami‘a Allahu liman hamidah","Bismillah","Astaghfirullah","Subhan Allah"],"answer":0,"explain":"\"Allah hears whoever praises Him\", followed by \"Rabbana wa laka al-hamd\"."}'::jsonb, 3);
